"""ms — quran_b."""

T = {
"quran_081": ("Tentang apakah manusia saling bertanya, pada permulaan Surah an-Naba'?", ["Berita besar", "Hujan", "Bintang-bintang", "Hasil tuaian"], "«Tentang apakah mereka saling bertanya? Tentang berita yang besar.»"),
"quran_082": ("Apakah maksud «al-Qari'ah», tajuk surah ke-101?", ["Hari yang menggemparkan", "Fajar", "Kafilah", "Gunung"], "«Al-Qari'ah! Apakah al-Qari'ah? Dan tahukah engkau apakah al-Qari'ah?» — ia salah satu nama Hari Kiamat."),
"quran_083": ("Dalam Surah al-Qari'ah, apakah yang menanti orang yang ringan timbangannya?", ["Tempat kembalinya ialah jurang (Hawiyah)", "Sebuah taman", "Sebuah mata air", "Sebuah rumah"], "«Adapun orang yang ringan timbangannya, maka tempat kembalinya ialah jurang yang dalam.»"),
"quran_084": ("Terhadap apakah Surah at-Takathur memberi amaran?", ["Berlumba-lumba menghimpun harta, yang melalaikan", "Perjalanan", "Kelaparan", "Diam"], "«Berlumba-lumba menghimpun harta telah melalaikan kamu, sehingga kamu masuk ke dalam kubur.»"),
"quran_085": ("Terhadap siapakah Surah al-Humazah dibuka dengan «Celakalah…»?", ["Setiap pengumpat lagi pencela", "Pengembara", "Orang yang tidur", "Orang miskin"], "«Celakalah bagi setiap pengumpat lagi pencela, yang mengumpul harta dan menghitungnya.»"),
"quran_086": ("Apakah yang diminta Surah Quraisy daripada kaum Quraisy, sebagai balasan perjalanan musim sejuk dan musim panas?", ["Menyembah Tuhan Rumah ini, yang memberi mereka makan dan keamanan", "Membina tembok", "Berhenti berniaga", "Berpindah ke Yaman"], "«Maka hendaklah mereka menyembah Tuhan Rumah ini, yang memberi mereka makan ketika lapar dan mengamankan mereka daripada ketakutan.»"),
"quran_087": ("Dengan pertanyaan apakah Surah asy-Syarh dibuka?", ["«Bukankah Kami telah melapangkan dadamu?»", "«Tidakkah engkau melihat?»", "«Siapakah yang menciptamu?»", "«Ke manakah engkau pergi?»"], "«Bukankah Kami telah melapangkan dadamu?»"),
"quran_088": ("Dengan apakah Allah bersumpah pada permulaan Surah at-Tin?", ["Demi buah tin, zaitun, bukit Sinai dan negeri yang aman ini", "Demi malam dan siang", "Demi bintang-bintang", "Demi laut"], "«Demi buah tin dan buah zaitun, demi bukit Sinai, dan demi negeri yang aman ini.»"),
"quran_089": ("Bagaimanakah Surah at-Tin menggambarkan penciptaan manusia?", ["Dalam bentuk yang sebaik-baiknya", "Lemah dan kecil", "Daripada api", "Daripada cahaya"], "«Sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya.»"),
"quran_090": ("Kota manakah yang disumpah Allah pada permulaan Surah al-Balad?", ["Makkah, tempat Nabi ﷺ tinggal", "Madinah", "Baitulmaqdis", "Taif"], "«Aku bersumpah demi negeri ini, dan engkau tinggal di negeri ini.»"),
"quran_091": ("Apakah «jalan yang mendaki» yang digambarkan Surah al-Balad?", ["Memerdekakan hamba, memberi makan anak yatim atau orang miskin pada hari kelaparan", "Merentasi padang pasir", "Mendaki gunung", "Menyeberangi laut"], "«Dan tahukah engkau apakah jalan yang mendaki itu? Iaitu memerdekakan hamba, atau memberi makan pada hari kelaparan kepada anak yatim yang ada pertalian kerabat, atau orang miskin yang sangat papa.»"),
"quran_092": ("Dengan apakah Allah bersumpah pada permulaan Surah al-Lail?", ["Demi malam apabila menutupi dan siang apabila terang", "Demi laut dan gunung", "Demi tin dan zaitun", "Demi kalam"], "«Demi malam apabila menutupi, demi siang apabila terang benderang… sesungguhnya usaha kamu memang berbeza-beza.»"),
"quran_093": ("Dengan perintah apakah Surah al-A'la dibuka?", ["«Sucikanlah nama Tuhanmu Yang Maha Tinggi»", "«Bacalah»", "«Bangunlah»", "«Dengarlah»"], "«Sucikanlah nama Tuhanmu Yang Maha Tinggi.»"),
"quran_094": ("Tentang apakah permulaan Surah al-Ghasyiyah bercakap?", ["Peristiwa yang meliputi: Hari Kiamat", "Sebuah perjalanan", "Sebuah pasar", "Sebuah peperangan"], "«Sudahkah datang kepadamu berita tentang peristiwa yang meliputi?»"),
"quran_095": ("Makhluk manakah yang diajak direnungi oleh Surah al-Ghasyiyah?", ["Unta, dan bagaimana ia diciptakan", "Singa", "Helang", "Ikan"], "«Maka tidakkah mereka memperhatikan unta, bagaimana ia diciptakan?»"),
"quran_096": ("Dengan apakah Allah bersumpah pada permulaan Surah al-Buruj?", ["Demi langit yang mempunyai gugusan bintang", "Demi bumi", "Demi sungai-sungai", "Demi awan"], "«Demi langit yang mempunyai gugusan bintang, dan demi Hari yang dijanjikan.»"),
"quran_097": ("Apakah yang dimaksudkan «at-Tariq», tajuk surah ke-86?", ["Bintang malam yang menembusi", "Pintu", "Jalan", "Guruh"], "«Demi langit dan yang datang pada malam hari — dan tahukah engkau apakah yang datang pada malam hari itu? Iaitu bintang yang menembusi.»"),
"quran_098": ("Peristiwa apakah yang digambarkan permulaan Surah az-Zalzalah?", ["Bumi digoncangkan dengan goncangannya", "Hujan lebat", "Angin kencang", "Gerhana"], "«Apabila bumi digoncangkan dengan goncangannya, dan bumi mengeluarkan beban-beban beratnya.»"),
"quran_099": ("Apakah ukuran yang ditetapkan pada penghujung Surah az-Zalzalah bagi amalan?", ["Seberat zarah, baik kebaikan mahupun kejahatan", "Segantang", "Setahun", "Setapak tangan"], "«Maka sesiapa yang melakukan kebaikan seberat zarah nescaya dia akan melihatnya, dan sesiapa yang melakukan kejahatan seberat zarah nescaya dia akan melihatnya.»"),
"quran_100": ("Apakah yang dimaksudkan «al-'Adiyat», tajuk surah ke-100?", ["Kuda perang yang berlari kencang sambil terengah-engah", "Angin", "Ombak", "Awan"], "«Demi kuda perang yang berlari kencang terengah-engah; yang mencetuskan api dengan pukulan kakinya; yang menyerbu pada waktu subuh.»"),
"quran_101": ("Bagaimanakah Surah al-Baqarah menggambarkan Kitab itu dalam ayat keduanya?", ["Kitab yang tiada keraguan padanya, petunjuk bagi orang bertakwa", "Kitab sejarah", "Kumpulan syair", "Kitab undang-undang semata-mata"], "«Kitab ini tiada keraguan padanya, petunjuk bagi orang yang bertakwa.»"),
"quran_102": ("Ayat manakah yang menjanjikan pemeliharaan Peringatan yang diturunkan?", ["«Sesungguhnya Kami yang menurunkan Peringatan, dan sesungguhnya Kami memeliharanya»", "«Tiada siapa akan membacanya»", "«Ia akan dilupakan»", "«Ia akan disembunyikan»"], "«Sesungguhnya Kami yang menurunkan al-Quran, dan sesungguhnya Kami benar-benar memeliharanya.»"),
"quran_103": ("Apakah hujah al-Quran tentang ketiadaan percanggahan di dalamnya?", ["Sekiranya ia daripada selain Allah, nescaya mereka mendapati banyak percanggahan di dalamnya", "Bahawa ia pendek", "Bahawa ia dalam bahasa Arab", "Bahawa ia purba"], "«Tidakkah mereka merenungi al-Quran? Sekiranya ia daripada selain Allah, nescaya mereka mendapati banyak percanggahan di dalamnya.»"),
"quran_104": ("Apakah yang dikatakan al-Quran akan berlaku kepada sebuah gunung, sekiranya ia diturunkan ke atasnya?", ["Ia akan tunduk dan berkecai kerana takut kepada Allah", "Ia akan bersinar", "Ia akan berpindah", "Ia akan menjadi hijau"], "«Sekiranya Kami turunkan al-Quran ini ke atas sebuah gunung, nescaya engkau melihatnya tunduk berkecai kerana takut kepada Allah.»"),
"quran_105": ("Bagaimanakah al-Quran memerintahkan ia dibaca, dalam Surah al-Muzzammil?", ["Dengan perlahan dan jelas (tartil)", "Sepantas mungkin", "Secara senyap", "Dengan nyanyian"], "«Dan bacalah al-Quran itu dengan tartil.»"),
"quran_106": ("Apakah yang perlu dilakukan apabila al-Quran dibacakan, menurut Surah al-A'raf?", ["Mendengar dan diam", "Menjawab dengan kuat", "Beredar", "Menulis"], "«Dan apabila al-Quran dibacakan, maka dengarlah dan diamlah, mudah-mudahan kamu dirahmati.»"),
"quran_107": ("Apakah yang diperintahkan al-Quran untuk diucapkan sebelum mula membacanya?", ["Memohon perlindungan Allah daripada syaitan yang direjam", "Mengira ayat", "Menyebut wuduk dengan kuat", "Membaca ayat terakhir"], "«Apabila engkau membaca al-Quran, mohonlah perlindungan kepada Allah daripada syaitan yang direjam.»"),
"quran_108": ("Mengapakah Kitab itu diturunkan, menurut Surah Sad?", ["Agar ayat-ayatnya direnungi dan orang yang berakal mengambil peringatan", "Agar ia disalin", "Agar ia dihitung", "Agar ia disembunyikan"], "«Ini sebuah Kitab yang penuh berkat yang Kami turunkan kepadamu, supaya mereka merenungi ayat-ayatnya.»"),
"quran_109": ("Cabaran apakah yang dilontarkan Surah al-Isra' kepada manusia dan jin sekali gus?", ["Membuat yang serupa dengan al-Quran ini, walaupun saling membantu", "Merentasi langit", "Mengira bintang", "Membina sebuah kota"], "«Sekiranya manusia dan jin berhimpun untuk membuat yang serupa dengan al-Quran ini, mereka tidak akan mampu membuatnya, walaupun mereka saling membantu.»"),
"quran_110": ("Doa apakah yang diajarkan al-Quran tentang ilmu?", ["«Wahai Tuhanku, tambahkanlah ilmuku»", "«Wahai Tuhanku, berilah aku harta»", "«Wahai Tuhanku, panjangkanlah umurku»", "«Wahai Tuhanku, bukakanlah jalan bagiku»"], "«Dan katakanlah: wahai Tuhanku, tambahkanlah ilmuku.»"),
"quran_111": ("Bagaimanakah Surah az-Zumar menggambarkan sebaik-baik perkataan yang diturunkan?", ["Sebuah Kitab yang serupa lagi berulang, yang menggeletar kulit kerananya", "Sebuah kitab pendek", "Sebuah kitab undang-undang", "Sebuah kitab bersyair"], "«Allah telah menurunkan sebaik-baik perkataan: sebuah Kitab yang serupa lagi berulang-ulang. Menggeletar kerananya kulit orang yang takut kepada Tuhan mereka.»"),
"quran_112": ("Dengan apakah al-Quran membandingkan kalimah yang baik, dalam Surah Ibrahim?", ["Dengan pokok yang baik, akarnya teguh dan dahannya menjulang ke langit", "Dengan sungai", "Dengan gunung", "Dengan bintang"], "«Kalimah yang baik itu seperti pokok yang baik, akarnya teguh dan dahannya menjulang ke langit; ia memberi buahnya pada setiap musim.»"),
"quran_113": ("Dengan apakah Surah ar-Ra'd membandingkan kebenaran dan kebatilan?", ["Dengan buih yang dihanyutkan arus, dan apa yang bermanfaat kepada manusia lalu kekal", "Dengan dua gunung", "Dengan dua kota", "Dengan dua kafilah"], "«Adapun buih itu akan hilang sebagai sampah; tetapi apa yang bermanfaat kepada manusia akan kekal di bumi.»"),
"quran_114": ("Dengan apakah hati menjadi tenang, menurut Surah ar-Ra'd?", ["Dengan mengingati Allah", "Dengan kekayaan", "Dengan perjalanan", "Dengan tidur"], "«Ketahuilah, dengan mengingati Allah hati menjadi tenang.»"),
"quran_115": ("Apakah yang dikatakan Surah al-Kahfi tentang dakwat yang diperlukan untuk menulis kalimah Allah?", ["Lautan akan kering sebelum habis kalimah Tuhannya", "Sebuah bekas dakwat memadai", "Semalam memadai", "Tujuh batang kalam memadai"], "«Sekiranya lautan menjadi dakwat untuk menulis kalimah Tuhanku, nescaya keringlah lautan itu sebelum habis kalimah Tuhanku.»"),
"quran_116": ("Berapa lautankah, menurut Surah Luqman, yang masih tidak akan menghabiskan kalimah Allah?", ["Tujuh lautan tambahan, dan masih tidak mencukupi", "Satu", "Tiga", "Dua belas"], "«Sekiranya semua pokok di bumi menjadi kalam dan lautan menjadi dakwat, ditambah lagi tujuh lautan sesudahnya, nescaya tidak akan habis kalimah Allah.»"),
"quran_117": ("Bantahan apakah yang dikatakan al-Quran akan dibangkitkan, sekiranya ia diturunkan dalam bahasa asing kepada seorang rasul Arab?", ["«Mengapa ayat-ayatnya tidak dijelaskan secara terperinci?»", "«Ia terlalu pendek»", "«Ia terlalu panjang»", "«Ia tiada tajuk»"], "«Sekiranya Kami jadikan al-Quran itu dalam bahasa asing, nescaya mereka berkata: “Mengapa ayat-ayatnya tidak dijelaskan?”»"),
"quran_118": ("Kepada apakah al-Quran memberi petunjuk, menurut Surah al-Isra'?", ["Kepada yang paling lurus", "Kepada kekayaan", "Kepada kekuasaan", "Kepada kerehatan"], "«Sesungguhnya al-Quran ini memberi petunjuk kepada yang paling lurus, dan memberi khabar gembira kepada orang beriman yang mengerjakan amal soleh dengan ganjaran yang besar.»"),
"quran_119": ("Bagaimanakah Surah Yunus menggambarkan apa yang turun daripada Tuhan?", ["Pengajaran, penawar bagi apa yang di dalam dada, petunjuk dan rahmat", "Sebuah perhitungan", "Sebuah titah raja", "Sebuah perjanjian"], "«Wahai manusia, sesungguhnya telah datang kepada kamu pengajaran daripada Tuhan kamu dan penawar bagi apa yang ada di dalam dada, serta petunjuk dan rahmat bagi orang beriman.»"),
"quran_120": ("Bagaimanakah Surah al-Baqarah menggambarkan peranan al-Quran sebagai pembeza?", ["Petunjuk bagi manusia, keterangan yang nyata, dan pembeza", "Sebuah kitab kira-kira", "Kumpulan kisah", "Kanun jenayah"], "«Bulan Ramadan yang padanya diturunkan al-Quran, menjadi petunjuk bagi manusia dan keterangan yang nyata tentang petunjuk serta pembeza.»"),
"quran_121": ("Dengan apakah Allah bersumpah pada permulaan Surah Qaf?", ["Demi al-Quran yang mulia", "Demi gunung", "Demi angin", "Demi fajar"], "«Qaf. Demi al-Quran yang mulia.»"),
"quran_122": ("Apakah yang dimaksudkan «al-Mursalat», tajuk surah ke-77?", ["Yang diutus, satu demi satu", "Kafilah", "Bintang-bintang", "Sungai-sungai"], "«Demi yang diutus berturut-turut, satu demi satu.»"),
"quran_123": ("Daftar manakah yang disebut Surah al-Mutaffifin bagi orang yang berbakti?", ["'Illiyyun", "Sijjin", "Al-Lauh", "Az-Zabur"], "«Catatan orang yang berbakti ada di 'Illiyyun… sebuah kitab yang bertulis, disaksikan oleh malaikat yang didekatkan.»"),
"quran_124": ("Dengan peristiwa apakah Surah al-Insyiqaq dibuka?", ["Langit yang terbelah", "Laut yang melimpah", "Bumi yang menghijau", "Matahari yang terbit"], "«Apabila langit terbelah, dan patuh kepada Tuhannya, dan sudah semestinya ia patuh.»"),
"quran_125": ("Dengan tanda apakah Surah at-Takwir dibuka?", ["Matahari yang digulung", "Bulan yang terbelah", "Angin yang bertiup", "Guruh"], "«Apabila matahari digulung, dan apabila bintang-bintang berjatuhan kehilangan cahayanya.»"),
"quran_126": ("Apakah yang dikatakan ayat terakhir Surah al-Baqarah tentang beban yang dipikulkan ke atas satu jiwa?", ["Allah tidak membebani satu jiwa melainkan menurut kemampuannya", "Setiap jiwa memikul dua kali ganda", "Tiada siapa diuji", "Semua beban sama"], "«Allah tidak membebani satu jiwa melainkan menurut kemampuannya.»"),
"quran_127": ("Dengan apakah al-Quran membandingkan perbelanjaan di jalan Allah?", ["Dengan sebutir benih yang menumbuhkan tujuh tangkai, setiap tangkai seratus biji", "Dengan sebuah batu", "Dengan sebuah perigi", "Dengan sebuah pelita"], "«Perumpamaan orang yang membelanjakan hartanya di jalan Allah ialah seperti sebutir benih yang menumbuhkan tujuh tangkai; pada tiap-tiap tangkai seratus biji.»"),
"quran_128": ("Dengan apakah dibandingkan sedekah yang dibatalkan oleh ungkitan dan sakitan hati?", ["Dengan batu licin bertanah, yang ditimpa hujan lebat lalu menjadi bersih licin", "Dengan pokok buah-buahan", "Dengan mata air", "Dengan sebuah rumah"], "«Perumpamaannya seperti batu licin yang di atasnya ada tanah, lalu ditimpa hujan lebat sehingga menjadi bersih licin.»"),
"quran_129": ("Dengan apakah al-Quran membandingkan amalan orang kafir dalam Surah an-Nur?", ["Dengan fatamorgana di tanah rata, yang disangka orang dahaga sebagai air", "Dengan sebuah gunung", "Dengan hujan", "Dengan sebuah taman"], "«Adapun orang yang kafir, amalan mereka seperti fatamorgana di tanah rata: orang yang dahaga menyangkanya air, sehingga apabila didatanginya dia tidak mendapati apa-apa.»"),
"quran_130": ("Soalan apakah yang membuka Surah al-'Ankabut, selepas huruf-huruf terpisah?", ["«Adakah manusia menyangka mereka dibiarkan berkata “kami beriman” tanpa diuji?»", "«Di manakah langit?»", "«Siapakah yang menciptakan laut?»", "«Apakah yang akan kamu lakukan esok?»"], "«Adakah manusia menyangka mereka akan dibiarkan berkata “kami beriman” sedangkan mereka tidak diuji?»"),
"quran_131": ("Bagaimanakah Surah Fatir menggambarkan para malaikat dalam ayat pertamanya?", ["Utusan yang mempunyai sayap, dua, tiga atau empat", "Dicipta daripada tanah liat", "Bilangannya tidak diketahui", "Menyerupai manusia"], "«Segala puji bagi Allah, Pencipta langit dan bumi, yang menjadikan malaikat sebagai utusan yang mempunyai sayap, dua, tiga dan empat.»"),
"quran_132": ("Tanda apakah yang disebut Surah ar-Rum tentang pasangan suami isteri?", ["Bahawa Dia menjadikan antara mereka kasih sayang dan rahmat", "Bahawa mereka hidup berasingan", "Bahawa mereka bekerja bersama", "Bahawa mereka mengembara"], "«Dan antara tanda-tanda-Nya ialah Dia menciptakan untuk kamu pasangan daripada jenis kamu sendiri, supaya kamu tenteram kepadanya, dan Dia menjadikan antara kamu kasih sayang dan rahmat.»"),
"quran_133": ("Dua tanda manakah yang disebut Surah ar-Rum sejurus selepas penciptaan langit dan bumi?", ["Perbezaan bahasa dan warna kulit", "Siang dan malam", "Angin dan hujan", "Laut dan gunung"], "«Dan antara tanda-tanda-Nya ialah penciptaan langit dan bumi, serta perbezaan bahasa dan warna kulit kamu.»"),
"quran_134": ("Daripada apakah Allah menjadikan setiap yang hidup, menurut Surah al-Anbiya'?", ["Daripada air", "Daripada api", "Daripada batu", "Daripada udara"], "«Dan Kami jadikan daripada air segala sesuatu yang hidup. Maka tidakkah mereka beriman?»"),
"quran_135": ("Apakah hujah al-Quran menentang adanya banyak tuhan, dalam Surah al-Anbiya'?", ["Sekiranya ada tuhan selain Allah, nescaya langit dan bumi binasa", "Mereka akan bersembunyi", "Mereka akan berdiam", "Mereka akan lenyap"], "«Sekiranya pada keduanya ada tuhan-tuhan selain Allah, nescaya binasalah keduanya.»"),
"quran_136": ("Tiga perkara manakah yang diperintahkan Allah menurut ayat 16:90?", ["Keadilan, berbuat ihsan, dan memberi kepada kaum kerabat", "Puasa, solat dan haji", "Perniagaan, perjalanan dan penulisan", "Diam, sabar dan mengasingkan diri"], "«Sesungguhnya Allah memerintahkan berlaku adil, berbuat ihsan, dan memberi kepada kaum kerabat.»"),
"quran_137": ("Daripada apakah, menurut Surah an-Nahl, keluar minuman pelbagai warna yang padanya ada penyembuh bagi manusia?", ["Daripada perut lebah", "Daripada laut", "Daripada pokok kurma", "Daripada mata air gunung"], "«Keluar daripada perutnya minuman yang bermacam-macam warnanya, padanya ada penyembuh bagi manusia.»"),
"quran_138": ("Bagaimanakah Surah ar-Rahman dibuka?", ["«Yang Maha Pemurah mengajarkan al-Quran»", "«Demi malam»", "«Segala puji bagi Allah»", "«Bacalah»"], "«Yang Maha Pemurah mengajarkan al-Quran, menciptakan manusia, dan mengajarnya pandai berbicara.»"),
"quran_139": ("Kepada berapa golongankah Surah al-Waqi'ah membahagikan manusia pada Hari Kiamat?", ["Tiga", "Dua", "Empat", "Tujuh"], "«Dan kamu menjadi tiga golongan: golongan kanan, golongan kiri, dan golongan yang terdahulu.»"),
"quran_140": ("Dengan apakah al-Quran membandingkan mereka yang memikul Taurat tetapi tidak mengamalkannya?", ["Dengan keldai yang memikul kitab-kitab", "Dengan burung", "Dengan gunung", "Dengan kapal"], "«Perumpamaan orang yang dipikulkan kepadanya Taurat kemudian mereka tidak memikulnya ialah seperti keldai yang memikul kitab-kitab.»"),
"quran_141": ("Wanita manakah yang dijadikan al-Quran teladan bagi orang beriman, dengan menyebut permohonannya untuk sebuah rumah di sisi Allah?", ["Isteri Firaun", "Ratu Saba'", "Isteri Nuh", "Isteri Lut"], "«Dan Allah menjadikan isteri Firaun teladan bagi orang yang beriman, ketika dia berkata: “Wahai Tuhanku, binakanlah untukku sebuah rumah di sisi-Mu dalam syurga.”»"),
"quran_142": ("Dengan nama lain apakah Surah al-Ikhlas sering dikenali, daripada temanya?", ["Surah keesaan (at-tauhid)", "Surah perjalanan", "Surah cahaya", "Surah rampasan"], "Al-Ikhlas, «pengabdian yang murni», juga dinamakan surah tauhid, kerana ia menggambarkan Allah sebagai Yang Maha Esa."),
"quran_143": ("Apakah yang dinafikan ayat ketiga Surah al-Ikhlas?", ["Bahawa Dia beranak atau diperanakkan", "Bahawa Dia berkuasa", "Bahawa Dia mendengar", "Bahawa Dia mencipta"], "«Dia tidak beranak dan tidak pula diperanakkan.»"),
"quran_144": ("Daripada apakah perlindungan dipohon dalam Surah an-Nas?", ["Pembisik yang bersembunyi, daripada jin dan manusia", "Ribut", "Penyakit", "Kemiskinan"], "«…daripada kejahatan pembisik yang bersembunyi, yang membisikkan ke dalam dada manusia, daripada jin dan manusia.»"),
"quran_145": ("Berapa kejahatan berlainankah yang disebut Surah al-Falaq selepas «kejahatan makhluk yang Dia ciptakan»?", ["Tiga: malam yang gelap, peniup pada simpulan, dan pendengki", "Satu", "Lima", "Tujuh"], "«…daripada kejahatan malam apabila gelap gelita, daripada kejahatan peniup pada simpulan, dan daripada kejahatan pendengki apabila dia dengki.»"),
"quran_146": ("Ayat manakah dalam al-Fatihah yang menyatakan inti ibadah dan permohonan pertolongan?", ["«Hanya kepada-Mu kami menyembah dan hanya kepada-Mu kami memohon pertolongan»", "«Segala puji bagi Allah»", "«Tunjukilah kami»", "«Penguasa Hari Pembalasan»"], "«Hanya kepada-Mu kami menyembah dan hanya kepada-Mu kami memohon pertolongan.»"),
"quran_147": ("Permohonan apakah yang menutup Surah al-Fatihah?", ["Ditunjukkan jalan yang lurus, jalan orang yang diberi nikmat", "Kekayaan", "Kemenangan", "Umur panjang"], "«Tunjukilah kami jalan yang lurus, jalan orang yang Engkau kurniakan nikmat.»"),
"quran_148": ("Dua jenis ayat manakah yang dibezakan Surah Ali 'Imran?", ["Ayat muhkamat (jelas) dan ayat mutasyabihat (samar)", "Yang panjang dan yang pendek", "Yang Makkiyah dan yang Madaniyah", "Yang dibaca dan yang ditulis"], "«Dialah yang menurunkan Kitab kepadamu: antaranya ada ayat-ayat muhkamat, itulah induk Kitab, dan yang lain ayat-ayat mutasyabihat.»"),
"quran_149": ("Apakah prinsip yang dinyatakan ayat 2:106 tentang ayat yang digantikan?", ["Allah mendatangkan yang lebih baik daripadanya atau yang sebanding", "Ia dipadam tanpa ganti", "Ia dilupakan", "Ia ditulis semula oleh manusia"], "«Kami tidak memansuhkan sesuatu ayat atau menjadikannya dilupakan melainkan Kami datangkan yang lebih baik daripadanya atau yang sebanding dengannya.»"),
"quran_150": ("Tentang apakah Rasul ﷺ akan mengadu kepada Tuhannya, menurut Surah al-Furqan?", ["Bahawa kaumnya meninggalkan al-Quran ini", "Bahawa dia letih", "Bahawa dia keseorangan", "Bahawa dia miskin"], "«Dan Rasul berkata: “Wahai Tuhanku, sesungguhnya kaumku menjadikan al-Quran ini sesuatu yang ditinggalkan.”»"),
}
